    24→
    25→    public void ProcessWithdrawals(Block block, IReleaseSpec spec)
    26→    {
    27→        if (!spec.WithdrawalsEnabled)
    28→            return;
    29→
    30→        if (_logger.IsTrace) _logger.Trace($"Applying withdrawals for block {block}");
    31→
    32→        if (block.Withdrawals is not null)
    33→        {
    34→            Withdrawal[] blockWithdrawals = block.Withdrawals;
    35→            for (int i = 0; i < blockWithdrawals.Length; i++)
    36→            {
    37→                Withdrawal withdrawal = blockWithdrawals[i];
