    26→namespace Nethermind.Consensus.AuRa
    27→{
    28→    public class AuRaBlockProcessor : BlockProcessor
    29→    {
    30→        private readonly ISpecProvider _specProvider;
    31→        private readonly IBlockFinder _blockTree;
    32→        private readonly AuRaContractGasLimitOverride? _gasLimitOverride;
    33→        private readonly ContractRewriter? _contractRewriter;
    34→        private readonly ITxFilter _txFilter;
    35→        private readonly ILogger _logger;
    36→
    37→        public AuRaBlockProcessor(ISpecProvider specProvider,
    38→            IBlockValidator blockValidator,
    39→            IRewardCalculator rewardCalculator,
    40→            IBlockProcessor.IBlockTransactionsExecutor blockTransactionsExecutor,
    41→            IWorldState stateProvider,
    42→            IReceiptStorage receiptStorage,
    43→            IBeaconBlockRootHandler beaconBlockRootHandler,
    44→            ILogManager logManager,
    45→            IBlockFinder blockTree,
    46→            IWithdrawalProcessor withdrawalProcessor,
    47→            IExecutionRequestsProcessor executionRequestsProcessor,
    48→            IAuRaValidator? auRaValidator,
    49→            ITxFilter? txFilter = null,
    50→            AuRaContractGasLimitOverride? gasLimitOverride = null,
    51→            ContractRewriter? contractRewriter = null)
    52→            : base(
    53→                specProvider,
    54→                blockValidator,
    55→                rewardCalculator,
    56→                blockTransactionsExecutor,
    57→                stateProvider,
    58→                receiptStorage,
    59→                beaconBlockRootHandler,
    60→                new BlockhashStore(specProvider, stateProvider),
    61→                logManager,
    62→                withdrawalProcessor,
    63→                executionRequestsProcessor)
    64→        {
    65→            _specProvider = specProvider;
    66→            _blockTree = blockTree ?? throw new ArgumentNullException(nameof(blockTree));
    67→            _logger = logManager?.GetClassLogger<AuRaBlockProcessor>() ?? throw new ArgumentNullException(nameof(logManager));
    68→            _txFilter = txFilter ?? NullTxFilter.Instance;
    69→            _gasLimitOverride = gasLimitOverride;
    70→            _contractRewriter = contractRewriter;
    71→            AuRaValidator = auRaValidator ?? new NullAuRaValidator();
    72→            if (blockTransactionsExecutor is IBlockProductionTransactionsExecutor produceBlockTransactionsStrategy)
    73→            {
    74→                produceBlockTransactionsStrategy.AddingTransaction += OnAddingTransaction;
    75→            }
    76→        }
    77→
    78→        public IAuRaValidator AuRaValidator { get; }
    79→
    80→        protected override TxReceipt[] ProcessBlock(Block block, IBlockTracer blockTracer, ProcessingOptions options, IReleaseSpec spec, CancellationToken token)
    81→        {
    82→            ValidateAuRa(block);
    83→            bool wereChanges = _contractRewriter?.RewriteContracts(block.Number, _stateProvider, spec) ?? false;
    84→            if (wereChanges)
    85→            {
    86→                _stateProvider.Commit(spec, commitRoots: true);
    87→            }
    88→            AuRaValidator.OnBlockProcessingStart(block, options);
    89→            TxReceipt[] receipts = base.ProcessBlock(block, blockTracer, options, spec, token);
    90→            AuRaValidator.OnBlockProcessingEnd(block, receipts, options);
    91→            Metrics.AuRaStep = block.Header?.AuRaStep ?? 0;
    92→            return receipts;
    93→        }
    94→
    95→        // After PoS switch we need to revert to standard block processing, ignoring AuRa customizations
    96→        protected TxReceipt[] PostMergeProcessBlock(Block block, IBlockTracer blockTracer, ProcessingOptions options, IReleaseSpec spec, CancellationToken token)
    97→        {
    98→            return base.ProcessBlock(block, blockTracer, options, spec, token);
    99→        }
   100→
   101→        // This validations cannot be run in AuraSealValidator because they are dependent on state.
   102→        private void ValidateAuRa(Block block)
   103→        {
   104→            if (!block.IsGenesis)
   105→            {
   106→                ValidateGasLimit(block);
   107→                ValidateTxs(block);
   108→            }
   109→        }
   110→
   111→        private BlockHeader GetParentHeader(Block block) =>
   112→            _blockTree.FindParentHeader(block.Header, BlockTreeLookupOptions.None)!;
   113→
   114→        private void ValidateGasLimit(Block block)
   115→        {
   116→            BlockHeader parentHeader = GetParentHeader(block);
   117→            if (_gasLimitOverride?.IsGasLimitValid(parentHeader, block.GasLimit, out long? expectedGasLimit) == false)
   118→            {
   119→                string reason = $"Invalid gas limit, expected value from contract {expectedGasLimit}, but found {block.GasLimit}";
   120→                if (_logger.IsWarn) _logger.Warn($"Proposed block is not valid {block.ToString(Block.Format.FullHashAndNumber)}. {reason}.");
   121→                throw new InvalidBlockException(block, reason);
   122→            }
   123→        }
   124→
   125→        private void ValidateTxs(Block block)
   126→        {
   127→            for (int i = 0; i < block.Transactions.Length; i++)
   128→            {
   129→                Transaction tx = block.Transactions[i];
   130→                AddingTxEventArgs args = CheckTxPosdaoRules(new AddingTxEventArgs(i, tx, block, block.Transactions));
   131→                if (args.Action != TxAction.Add)
   132→                {
   133→                    string reason = $"{tx.ToShortString()} doesn't have required permissions: {args.Reason}";
   134→                    if (_logger.IsWarn) _logger.Warn($"Proposed block is not valid {block.ToString(Block.Format.FullHashAndNumber)}. {reason}.");
   135→                    throw new InvalidBlockException(block, reason);
   136→                }
   137→            }
   138→        }
   139→
   140→        private void OnAddingTransaction(object? sender, AddingTxEventArgs e)
   141→        {
   142→            CheckTxPosdaoRules(e);
   143→        }
   144→
   145→        private AddingTxEventArgs CheckTxPosdaoRules(AddingTxEventArgs args)
   146→        {
   147→            AcceptTxResult? TryRecoverSenderAddress(Transaction tx, BlockHeader parentHeader, IReleaseSpec currentSpec)
   148→            {
   149→                if (tx.Signature is not null)
   150→                {
   151→                    EthereumEcdsa ecdsa = new(_specProvider.ChainId);
   152→                    Address txSenderAddress = ecdsa.RecoverAddress(tx, !currentSpec.ValidateChainId);
   153→                    if (tx.SenderAddress != txSenderAddress)
   154→                    {
   155→                        if (_logger.IsWarn) _logger.Warn($"Transaction {tx.ToShortString()} in block {args.Block.ToString(Block.Format.FullHashAndNumber)} had recovered sender address on validation.");
   156→                        tx.SenderAddress = txSenderAddress;
   157→                        return _txFilter.IsAllowed(tx, parentHeader, currentSpec);
   158→                    }
   159→                }
